        let speculative = session
            .import_demand_frontier_for_roots(
                revision,
                &plan,
                ImportDemandMode::Speculative,
                &plan.demand_roots(),
            )
            .unwrap();
        assert!(speculative.requests().is_empty());
        assert!(speculative.speculative_blocked());
